package com.sliverzfx.gothicquest

internal object GothicRemakeChapter1Data {
    val quests: List<Quest> = listOf(
        GothicRemakeQuestData.quest(1, 1, "A Few Drops Too Much", "Side quest", "Rice Lord", "New Camp", "Help Silas settle Rayk’s dispute: speak to Silas, find Rayk in the pub, defeat him without killing him, then report back.", "300 XP", "A knockout is sufficient; do not kill Rayk."),
        GothicRemakeQuestData.quest(1, 2, "A Letter from the Fire Mages", "Side quest", "Torrez", "Old Camp → castle", "Keep the letter sealed. Once admitted to a camp, deliver it to Milten in the Old Camp castle and return to Torrez to choose the reward.", "400 XP and choice of reward", "Opening the letter costs experience and changes the reward. Handing it to Torrez instead of Milten pays less."),
        GothicRemakeQuestData.quest(1, 3, "A Piece Of The Pie", "Side quest", "Baal Kagan", "New Camp → Silas’ pub", "Get into Silas’ pub, persuade Baal Isidro to hand over his swampweed, sell it around the camp, then settle the proceeds with Lares and Isidro.", "500 XP", "The quest can require you to choose who receives the proceeds; satisfying both costs ore."),
        GothicRemakeQuestData.quest(1, 4, "A Ring for Fingers", "Side quest", "Fingers", "Old Camp", "Earn Fingers’ approval by taking the ring from Scatty’s locked chest and bringing it back.", "Old Camp admission support", "Theft is easiest at night; bring lockpicks."),
        GothicRemakeQuestData.quest(1, 5, "Aaron's Chest", "Side quest", "Snipes", "Old Mine", "Lure Aaron away by telling him Ian wants him; Snipes pays you 10 ore and offers Aaron’s chest key for 30 ore. Open the chest, then optionally sell the key back to Aaron for 20 ore.", "150 XP; up to 10 ore net", "Snipes’ chest-key deal is optional; account for the 30-ore purchase and 20-ore resale."),
        GothicRemakeQuestData.quest(1, 6, "Admission to the Swamp Camp", "Main quest", "Baal Parvez / Baal Kagan", "Swamp Camp", "Get escorted to the Swamp Camp, ask Joru for the Baals’ tasks, then win four endorsements: stage Baal Namib’s dialogue with Lester, give Baal Tyon Kagan’s prepared Dreamcall, complete Orun’s harvest chain, use Orun’s Sleep scroll for Cadar, and bring Dusty to Tondral. Report four votes to Cor Kalom.", "3,850 XP; Novice’s Armor", "Joining any one of the three camps cancels admission quests for the other two. The prepared Dreamcall depends on Customer Recruitment."),
        GothicRemakeQuestData.quest(1, 7, "Aiming High", "Side quest", "Theron", "Swamp Camp eastern beach", "Find Theron on the eastern beach, bring six Black Sage, learn Climbing for 5 learning points, then follow him up the nearby cliff. Check the chairs at his retreat for the Fist of Wind inscription.", "100 XP; Climbing training", "You need to learn Climbing before Theron will lead you to the retreat."),
        GothicRemakeQuestData.quest(1, 8, "Baloro's Weapon", "Side quest", "Baloro", "Free Mine / Kessel area", "Bring Baloro 5 apples, 2 rice schnapps, 5 beers, 3 bread, 2 cheese and 2 grapes. He takes the food and admits the promised weapon was a joke.", "300 XP; no weapon", "Do not expect a weapon reward. The grapes can be scarce; check Wolf’s stock and the listed free locations."),
        GothicRemakeQuestData.quest(1, 9, "Beak Performance", "Side quest", "Cohsel", "Kingstide lake near the Old Camp", "Bring Cohsel 5 Kingstide from the lake bottom. Then bring 3 wolf pelts and 2 leather strips for a saddle, wait until noon the next day and collect the Scavenger Whistle.", "Scavenger Whistle; riding mount", "Diving training from Homer makes collecting the algae easier; Cohsel needs a day to craft the saddle."),
        GothicRemakeQuestData.quest(1, 10, "Beasts of Khorinis I", "Side quest", "Cavalorn", "Cavalorn’s hunting hut", "Find the first bestiary volume and bring it to Cavalorn to learn how to harvest creature trophies.", "Trophy-harvesting knowledge", "The volume unlocks useful trophy skills; do not sell it."),
        GothicRemakeQuestData.quest(1, 11, "Beasts of Khorinis III", "Side quest", "Cavalorn", "Orc territory south of the Old Camp", "Find Bestiary III in an unlocked chest in a cave just inside the orc territory. Give it to Cavalorn to learn Take Scutes, then bring him 3 lizard bone scutes.", "850 XP; trophy skill", "Learn Take Scutes before hunting; the marked lizards behind the Sunken Tower are a reliable remaining source."),
        GothicRemakeQuestData.quest(1, 12, "Beasts of Khorinis IV", "Side quest", "Cavalorn", "Shrat’s house → swamp", "Take Bestiary IV from the table in Shrat’s house to Cavalorn and learn Take Shark Skin. Bring 2 swampshark chitin plates and 1 swampshark skin; one swampshark yields all three trophies.", "1,000 XP; 250 ore", "Swampsharks are dangerous. The guide recommends ranged attacks or Ball Lightning rather than early melee."),
        GothicRemakeQuestData.quest(1, 13, "By the Hand of a Master", "Side quest", "Haenno", "New Camp lakeshore by Silas’ Pub", "Tell Haenno you know archery and choose willow, oak or ironwood. Meet the Dexterity requirement for the selected bow and return the next day to collect it.", "100 XP; choice of bow", "Ironwood needs 27 Dexterity; oak 24; willow 20. The strongest bow is not available to every build early."),
        GothicRemakeQuestData.quest(1, 14, "Casting Shadows (Joining the Old Camp)", "Main quest", "Diego", "Old Camp", "Complete Diego’s test and enough tasks for the Shadows, then report to Thorus and Gomez to join the Old Camp.", "Shadow’s Dress", "Joining a camp closes the other two admission routes. Finish desired camp tasks first."),
        GothicRemakeQuestData.quest(1, 15, "Customer Recruitment", "Side quest", "Baal Kagan", "New Camp", "Distribute Kagan’s swampweed among ten customers and return for your reward.", "200 XP; prepared Dreamcall choice", "Choose the prepared Dreamcall if you want the Brotherhood admission route."),
        GothicRemakeQuestData.quest(1, 16, "Horatio the Peasant", "Side quest", "Horatio", "New Camp rice fields", "Learn Horatio’s story from Jeremiah, then explain that you oppose the Rice Lord’s abuse so Horatio will teach you his strength technique.", "Permanent +5 Strength", "The reward is a permanent stat increase; collect it when it best fits your build."),
        GothicRemakeQuestData.quest(1, 17, "Joining the New Camp", "Main quest", "Lares", "New Camp", "Complete enough New Camp errands and show Lares you can contribute before accepting bandit status.", "2,950 XP; Bandit’s Dress", "Joining a camp closes the other two admission routes."),
        GothicRemakeQuestData.quest(1, 18, "Lurker at the Dam", "Side quest", "Homer", "New Camp dam", "Find and kill the lurker damaging Homer’s dam, then report back to Homer.", "300 XP", "The shoreline fight is easier if you draw the lurker onto dry ground."),
        GothicRemakeQuestData.quest(1, 19, "New Fence for Fisk", "Side quest", "Fisk", "Old Camp → New Camp", "After driving Mordrag away non-lethally, persuade Sharky in the New Camp to replace him as Fisk’s fence.", "300 XP", "This setup depends on the non-lethal solution to Out of Sight."),
        GothicRemakeQuestData.quest(1, 20, "New Souls for the Brotherhood", "Side quest", "Baal Tondral", "Old Camp", "Help Baal Tondral recruit a suitable newcomer for the Brotherhood and report the result.", "500 XP", "Listen to the candidate’s dialogue before promising anything."),
        GothicRemakeQuestData.quest(1, 21, "Out of Sight", "Side quest", "Thorus", "Old Camp", "Remove Mordrag from the Old Camp as Thorus ordered; escort him away or drive him out without killing him.", "300 XP", "The non-lethal knock-out route enables New Fence for Fisk; escorting Mordrag preserves his New Camp introduction."),
        GothicRemakeQuestData.quest(1, 22, "Recipe of the Sect", "Side quest", "Dexter", "Old Camp → Swamp Camp", "Steal Cor Kalom’s swampweed recipe from the laboratory and deliver it to Dexter.", "350 XP", "Save before stealing; being seen can turn the camp hostile."),
        GothicRemakeQuestData.quest(1, 23, "Relief for Ghorim", "Side quest", "Ghorim", "Swamp Camp", "Take over Ghorim’s exhausting weed-cutting shift so he can rest, then report to Baal Orun.", "400 XP", "Talk to Baal Orun after completing the shift to unlock his larger harvest task."),
        GothicRemakeQuestData.quest(1, 24, "Shrike's Hut", "Side quest", "Shrike", "New Camp", "Resolve Shrike’s claim to a hut in the New Camp and make sure the hut is cleared for its owner.", "200 XP", "Use dialogue and a non-lethal fight where possible."),
        GothicRemakeQuestData.quest(1, 25, "Snaf's Recipe", "Side quest", "Snaf", "Old Camp", "Collect the hell mushrooms and meatbug meat Snaf needs, then bring the ingredients back to him.", "100 XP; recurring meatbug ragout", "Gather the ingredients outside the south gate while doing nearby errands."),
        GothicRemakeQuestData.quest(1, 26, "Something the Matter?", "Side quest", "Lares", "New Camp", "Ask Lares what is troubling him and follow his lead to uncover the problem affecting the New Camp.", "750 XP", "Exhaust Lares’ dialogue; the quest is tied to New Camp business."),
        GothicRemakeQuestData.quest(1, 27, "Special Pieces", "Side quest", "Santino", "Old Mine", "Collect the special pieces Santino wants from the Old Mine and bring the complete set back to him.", "750 XP; 1,000 ore", "Check the mine’s side passages and speak with Santino about the exact pieces."),
        GothicRemakeQuestData.quest(1, 28, "The Amulet", "Side quest", "Bloodwyn", "Old Camp", "Deal with Bloodwyn’s demand for an amulet and settle the matter through the quest dialogue.", "200 XP", "The quest no longer starts simply by refusing to pay Bloodwyn; speak to him and follow the journal trigger."),
        GothicRemakeQuestData.quest(1, 29, "The forgotten Recipe", "Side quest", "Brock", "Old Camp", "Find the forgotten recipe Brock is looking for and return it so he can prepare his stew.", "100 XP; Brock’s Stew", "Search the Old Camp kitchens and nearby storage carefully."),
        GothicRemakeQuestData.quest(1, 30, "The Gloves Are Off", "Side quest", "Old Camp arena", "Old Camp", "Accept the arena challenge and win the fistfight to settle the dispute.", "250 XP", "Remove weapons and use the arena rules; avoid killing the opponent."),
        GothicRemakeQuestData.quest(1, 31, "The Lurker´s Bite", "Side quest", "Old Camp hunter", "Valley of Mines", "Bring the hunter the lurker material requested for his leatherwork.", "100 XP; leather strips", "Learn the appropriate harvesting skill before killing the lurker."),
        GothicRemakeQuestData.quest(1, 32, "The Price of Magic", "Side quest", "Torrez", "Old Camp", "Speak with Torrez about magic and complete his request to earn a Fire Bolt rune.", "250 XP; Fire Bolt rune", "Keep the rune reward in mind if you plan to learn magic."),
        GothicRemakeQuestData.quest(1, 33, "The Raid", "Side quest", "New Camp", "Valley of Mines", "Help the New Camp carry out its raid and report to the camp after the operation.", "Quest XP", "Finish preparations and speak to the involved bandits before leaving camp."),
        GothicRemakeQuestData.quest(1, 34, "The Swampweed Harvest", "Side quest", "Baal Orun", "Swamp Camp", "Collect the swampweed harvest from the field workers and deliver it to Cor Kalom.", "1,150 XP; Sleep scroll", "Finish Relief for Ghorim first so Baal Orun will entrust the full harvest to you."),
        GothicRemakeQuestData.quest(1, 35, "The vanished Warder", "Side quest", "Swamp Camp", "Swamp Camp", "Investigate the disappearance of a Brotherhood warder and report what you discover to the camp.", "250 XP", "Question the camp members and search the routes outside the palisade."),
        GothicRemakeQuestData.quest(1, 36, "Thirsty Farmers", "Side quest", "Rice Lord", "New Camp rice fields", "Distribute water to the rice-field workers and deal with Lefty when he tries to make the chore permanent.", "300 XP", "Do not let Lefty turn the one-time task into a daily obligation."),
        GothicRemakeQuestData.quest(1, 37, "Trial of Trust", "Main quest", "Diego", "Old Mine", "Retrieve Ian’s demand list from the Old Mine and return it to Diego without altering it.", "750 XP", "Keep the list untouched for Diego’s test; the New Camp has its own route to exploit it."),
        GothicRemakeQuestData.quest(1, 38, "Ulbert's Storage", "Side quest", "Ulbert", "Old Camp castle", "Find Ulbert’s hidden storage and recover the supplies he has stashed there.", "75 XP", "Ask the castle workers for clues before searching locked storage."),
        GothicRemakeQuestData.quest(1, 39, "Up to His Neck", "Side quest", "Rice Lord", "New Camp", "Help a New Camp resident caught up in the Rice Lord’s business and report the resolution.", "450 XP", "Talk to the Rice Lord and the person in trouble before choosing how to intervene."),
        GothicRemakeQuestData.quest(1, 40, "Whistler's Sword", "Side quest", "Whistler", "Old Camp", "Buy Whistler’s sword from Fisk and bring it back to Whistler.", "Quest XP; sword", "Agree on the price with Whistler before spending your ore.")
    )
